#define main near_history
#include "six_near.cpp"
#undef main
struct State{array<Word,8> masks{};array<int,28> priorities{};unsigned value=~0U;};
int main(int argc,char** argv){assert(argc==3);int trials=stoi(argv[1]);mt19937 random(stoul(argv[2]));string key;int order,target,paired,size;while(cin>>key>>order>>target>>paired>>size){assert(((order==32&&paired)||(order==31&&!paired))&&target==10&&size>0);Adj base{};for(int idx=0;idx<order;++idx)cin>>base[idx];vector<Word> masks(size);for(auto& mask:masks)cin>>mask;vector<pair<int,int>> possible;for(int high=1;high<8;++high)for(int low_slot=0;low_slot<high;++low_slot)possible.emplace_back(order+low_slot,order+high);unsigned best=~0U;int accepted=0;State state,record;
    for(int trial=0;trial<trials;++trial){State next=state;bool restart=trial%512==0||state.value==~0U;if(restart){for(auto& mask:next.masks)mask=masks[random()%size];for(int idx=0;idx<28;++idx)next.priorities[idx]=idx;shuffle(next.priorities.begin(),next.priorities.end(),random);if(best!=~0U&&random()%4==0){next=record;next.masks[random()%8]=masks[random()%size];}}else{for(int rep=0,edits=1+(random()%5==0)+(random()%13==0);rep<edits;++rep){if(random()%4){int slot=random()%8;Word mask=masks[random()%size];if(random()%4==0)mask=((next.masks[slot^1]&0x55555555ULL)<<1)|((next.masks[slot^1]>>1)&0x55555555ULL);next.masks[slot]=mask;}else swap(next.priorities[random()%28],next.priorities[random()%28]);}}
    Adj graph=base;for(int slot=0;slot<8;++slot){Word contact=next.masks[slot];if(!paired&&find(masks.begin(),masks.end(),contact)==masks.end()){contact=masks[random()%size];next.masks[slot]=contact;}for(Word rest=contact;rest;rest&=rest-1){int vertex=__builtin_ctzll(rest);connect(graph,vertex,order+slot);if(paired&&(contact&bit(vertex^1)))graph[vertex]&=~bit(vertex^1);}}
    bool bad=false;if(paired)for(int vertex=0;vertex<order;vertex+=2){if(max(count(graph[vertex]),count(graph[vertex+1]))>9){graph[vertex]&=~bit(vertex+1);graph[vertex+1]&=~bit(vertex);}if(max(count(graph[vertex]),count(graph[vertex+1]))>9)bad=true;}if(bad)continue;
    for(int idx:next.priorities){auto [left,right]=possible[idx];if(count(graph[left])<9&&count(graph[right])<9&&!(graph[left]&graph[right]))connect(graph,left,right);}int total=0;for(int vertex=0;vertex<order+8;++vertex){int degree=count(graph[vertex]);total+=degree;if(degree<6||degree>9)bad=true;}if(bad||total<322)continue;++accepted;
    unsigned limit=restart?~0U:state.value+1+(random()%19==0?7:0);unsigned score=number(graph,bit(order+8)-1,10,limit);if(score>=limit)continue;next.value=score;state=next;if(score<best){best=score;record=state;cout<<key<<" best "<<trial<<' '<<score<<' '<<total/2<<" graph";for(int vertex=0;vertex<order+8;++vertex)cout<<' '<<graph[vertex];cout<<endl;if(!best)break;}}
    cout<<key<<" trials "<<trials<<" accepted "<<accepted<<" best "<<best<<endl;}}
